mapper.select:
select 
from preg_todo t
where t.del_flag = '0'

    and t.done = #{done}


    and t.due_date >= #{from}


    and t.due_date <= #{to}

order by t.done asc, t.due_date asc, t.due_time asc, t.id asc

select t.due_date as dueDate, count(1) as total
from preg_todo t
where t.due_date >= #{from}
  and t.due_date <= #{to}
  and t.del_flag = '0'
group by t.due_date
